int maxBlackSquare(int **matrix, int matrixSize, int *matrixColSize) {
  int n = matrixSize;
  int **dp = (int **)malloc(sizeof(int *) * n);
  for (int i = 0; i < n; i++) dp[i] = (int *)calloc(n, sizeof(int));
  int best = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < matrixColSize[i]; j++) {
      if (matrix[i][j] == 1) {
        if (i == 0 || j == 0) {
          dp[i][j] = 1;
        } else {
          int m = dp[i - 1][j - 1] < dp[i - 1][j] ? dp[i - 1][j - 1] : dp[i - 1][j];
          if (dp[i][j - 1] < m) m = dp[i][j - 1];
          dp[i][j] = m + 1;
        }
        if (dp[i][j] > best) best = dp[i][j];
      }
    }
  }
  for (int i = 0; i < n; i++) free(dp[i]);
  free(dp);
  return best;
}

class Solution {
public:
  int maxBlackSquare(vector<vector<int>> &matrix) {
    int n = matrix.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));
    int best = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < (int)matrix[i].size(); j++) {
        if (matrix[i][j] == 1) {
          if (i == 0 || j == 0) {
            dp[i][j] = 1;
          } else {
            dp[i][j] = min(dp[i - 1][j - 1], min(dp[i - 1][j], dp[i][j - 1])) + 1;
          }
          best = max(best, dp[i][j]);
        }
      }
    }
    return best;
  }
};

